'use strict';
const {skills,posts}=window.FIELDNOTES;
const names={'website-ui':'Website & UI','video':'Video & storytelling','coding':'Coding','token-context':'Token & context','research-automation':'Research & automation','skill-engineering':'Skill engineering'};
const statuses={'verified-static':'Official static evidence','upstream-claimed':'Upstream claims support','unknown':'Unknown compatibility'};
const $=s=>document.querySelector(s);
function el(tag,cls,text){const node=document.createElement(tag);if(cls)node.className=cls;if(text!==undefined)node.textContent=text;return node;}
function link(href,text,cls){const node=el('a',cls,text);node.href=href;if(href.startsWith('https:')){node.target='_blank';node.rel='noopener noreferrer';}return node;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=link(url,'');a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copy(text,button){try{await navigator.clipboard.writeText(text);const old=button.textContent;button.textContent='Copied ✓';setTimeout(()=>button.textContent=old,1800);}catch{toast('Clipboard unavailable. Select the command in Details to copy it.');}}
$('#nav-count').textContent=skills.length;$('#skill-count').textContent=skills.length;$('#post-count').textContent=String(posts.length).padStart(2,'0');
for(const [category,name] of Object.entries(names)){const count=skills.filter(s=>s.category===category).length;const a=link('#library/'+category,name);a.append(el('span','',String(count).padStart(2,'0')));$('#topic-links').append(a);const o=el('option','',name);o.value=category;$('#category-select').append(o);}
let postFilter='All';
function renderPosts(){const query=$('#report-search').value.trim().toLowerCase();const found=posts.filter(p=>(postFilter==='All'||p.category===postFilter)&&JSON.stringify([p.title,p.excerpt,p.markdown]).toLowerCase().includes(query));$('#posts').replaceChildren();$('#report-empty').hidden=!!found.length;for(const p of found){const row=link('#article/'+p.slug,'','post-row');const icon=el('div','post-icon'+(p.category==='Discovery'?' discovery':''),p.category==='Discovery'?'↗':'Aa');icon.setAttribute('aria-hidden','true');icon.append(el('small','',p.category==='Discovery'?'SOURCE SNAPSHOT':'DESIGN NOTES'));const info=el('div','post-info');const meta=el('div','meta');meta.append(el('span','tag',p.category.toUpperCase()),el('span','',p.date+' · '+p.readTime+' MIN'));info.append(meta,el('h3','post-title',p.title),el('p','',p.excerpt));row.append(icon,info,el('span','post-arrow','↗'));$('#posts').append(row);}}
$('#report-search').addEventListener('input',renderPosts);$('#post-filters').addEventListener('click',e=>{const button=e.target.closest('[data-post-filter]');if(!button)return;postFilter=button.dataset.postFilter;for(const b of $('#post-filters').querySelectorAll('button')){b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',b===button?'true':'false');}renderPosts();});
function renderSkills(){const query=$('#skill-search').value.trim().toLowerCase(),category=$('#category-select').value,compat=$('#compat-select').value;const found=skills.filter(s=>(category==='all'||s.category===category)&&(compat==='all'||s.codex.status===compat)&&JSON.stringify([s.id,s.invocation,s.summary,s.reason,s.requirements,s.repo]).toLowerCase().includes(query));$('#skills').replaceChildren();$('#library-results').textContent=found.length+' of '+skills.length+' skills';$('#skill-empty').hidden=!!found.length;for(const s of found){const card=el('article','skill-card');const top=el('div','card-top');top.append(el('span','tag',names[s.category].toUpperCase()),el('span','',s.stars.toLocaleString('en-US')+' stars · '+s.observed_at));card.append(top,el('h2','',s.id),el('p','',s.summary),el('span','badge '+s.codex.status,statuses[s.codex.status]));const details=el('details');details.append(el('summary','','Evidence & installation'));details.append(el('p','',s.reason),el('p','',s.requirements),el('p','','Source: '+s.repo+' · Commit '+s.commit.slice(0,12)),el('p','','No Codex runtime test recorded.'));const cmd=s.installable?'python3 skills.py install '+s.id+' --dest /path/to/project/.agents/skills --reviewed':'Upstream installation required; inspect the pinned README and dependencies.';details.append(el('code','',cmd),el('code','','$'+s.invocation+' <your task>'));details.append(link('https://github.com/'+s.repo+'/blob/'+s.commit+'/README.md','Pinned setup instructions ↗'));const actions=el('div','card-actions');actions.append(link(s.source,'Read the source ↗'));const button=el('button','','Copy invocation');button.type='button';button.addEventListener('click',()=>copy('$'+s.invocation+' <your task>',button));actions.append(button);card.append(details,actions);$('#skills').append(card);}}
for(const id of ['skill-search','category-select','compat-select'])$('#'+id).addEventListener(id==='skill-search'?'input':'change',renderSkills);
function article(slug){const p=posts.find(p=>p.slug===slug);const container=$('#article');container.replaceChildren();if(!p){container.append(el('h1','','Report not found'),el('p','','Return to the notebook to choose an available report.'));return;}
const head=el('header','article-header');head.append(el('span','tag',p.category.toUpperCase()),el('h1','',p.title));const meta=el('div','meta');meta.append(el('span','',p.date),el('span','',p.readTime+' minute read'),el('span','','AI Skills Library'));head.append(meta);const actions=el('div','article-actions');actions.append(link(p.source,'View Markdown source ↗'));const exportButton=el('button','','Download report ↓');exportButton.type='button';exportButton.addEventListener('click',()=>download(p.slug+'.md',p.markdown));actions.append(exportButton);head.append(actions);const body=el('article','prose');body.innerHTML=p.html;container.append(head,body);document.title=p.title+' — Fieldnotes';}
function route(){const value=location.hash.slice(1)||'reports';const [page,key]=value.split('/');const known=['reports','library','article','draft','about'];const target=known.includes(page)?page:'reports';for(const view of document.querySelectorAll('.view'))view.hidden=view.id!==target+'-view';for(const a of document.querySelectorAll('[data-nav]')){const active=a.dataset.nav===(target==='article'?'reports':target);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}document.title='Fieldnotes — AI Skills Library';if(target==='article')article(key);if(target==='library'){$('#category-select').value=names[key]?key:'all';renderSkills();}window.scrollTo(0,0);}
try{const stored=JSON.parse(localStorage.getItem('fieldnotes-draft')||'null');if(stored){$('#draft-title').value=String(stored.title||'');$('#draft-body').value=String(stored.body||'');$('#draft-status').textContent='Your previous browser draft has been restored.';}}catch{$('#draft-status').textContent='Browser storage unavailable. Export your draft to keep it.';}
$('#draft-form').addEventListener('submit',e=>{e.preventDefault();try{localStorage.setItem('fieldnotes-draft',JSON.stringify({title:$('#draft-title').value,body:$('#draft-body').value}));$('#draft-status').textContent='Saved in this browser. Export Markdown to add it to the repository.';}catch{$('#draft-status').textContent='Could not save to browser storage. Use Export .md to keep your work.';}});
$('#export-draft').addEventListener('click',()=>{if(!$('#draft-form').reportValidity())return;const title=$('#draft-title').value.trim(),body=$('#draft-body').value;const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Hong_Kong',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const slug=title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,70)||'fieldnote';download(date+'-'+slug+'.md','# '+title+'\n\n'+body+'\n');$('#draft-status').textContent='Markdown exported. Add it to reports/ and rebuild to publish.';});
window.addEventListener('hashchange',route);renderPosts();renderSkills();route();

$('.skip').addEventListener('click',event=>{event.preventDefault();$('#content').focus();});
